const actions = {
    activateTool({ commit }, _active) {
        commit('ACTIVATE_TOOL', _active);
        commit('SHOW_ERRORS', false);
    },
    updateColor({ commit }, colorData) {
        let choice = '';
        commit('SHOW_ERRORS', false);

        let colorsArray = state.colorLookUp;
        let findColor = Object.entries(colorsArray).find(([key, value]) => key === colorData.sku);
        let isClear = findColor !== undefined ? findColor[1].Type === 'clear' : false;

        if((findColor !== undefined) && !isClear) {
            choice = findColor[1];
            commit('UPDATE_COLOR', choice);
        } else {
            if(state.isActive) {
                commit('SHOW_ERRORS', true);
            }
        }

        if(state.isActive) {
            if(state.toolState === toolStage[3]) {
                commit('UPDATE_TOOL_STATE', 2);
            }
        }
    },
    updateEyeShadow({ commit }, eyeShadowData) {
        commit('SHOW_ERRORS', false);
        commit('SET_SELECTED_SKU', eyeShadowData.sku);

        let findEyeShadows = Object.entries(state.eyeShadows).find(([key, value]) => key === eyeShadowData.sku);
        if(findEyeShadows !== undefined && state.selectedModel > -1) {
            let face = findEyeShadows[1][state.selectedModel].Face;
            commit('UPDATE_OVERLAY_IMAGE', face);
        } else {
            if(state.isActive) {
                commit('SHOW_ERRORS', true);
            }
        }

        if(state.isActive) {
            if(state.toolState === toolStage[3]) {
                commit('UPDATE_TOOL_STATE', 2);
            }
        }
    },
    updateBlush({ commit }, blushData) {
        commit('SHOW_ERRORS', false);
        commit('SET_SELECTED_SKU', blushData.sku);

        let findBlush = Object.entries(state.blushArray).find(([key, value]) => key === blushData.sku);
        if(findBlush !== undefined && state.selectedModel > -1) {
            let face = findBlush[1][state.selectedModel].Face;
            commit('UPDATE_OVERLAY_IMAGE', face);
        } else {
            if(state.isActive) {
                commit('SHOW_ERRORS', true);
            }
        }

        if(state.isActive) {
            if(state.toolState === toolStage[3]) {
                commit('UPDATE_TOOL_STATE', 2);
            }
        }
    },
    updateToolState({ commit }, _stage) {
        commit('UPDATE_TOOL_STATE', _stage);
        commit('SHOW_ERRORS', false);
    },
    setModel({ commit }, modelData) {
        commit('SET_MODEL', modelData);
        commit('SHOW_ERRORS', false);
    }
};

const getters = {};

const mutations = {
    ACTIVATE_TOOL(state, active) {
        let stage = active ? 3 : 1;
        state.isActive = active !== false;
        state.toolState = toolStage[stage];
        if(!state.isActive) {
            setTimeout(() => {
                window.refreshProdMedia && window.refreshProdMedia();
            }, 0);
        }
    },
    SET_COLOR_DATA(state, colorData) {
        state.colorLookUp = colorData;
    },
    SET_MODEL(state, modelData) {
        state.selectedModel = modelData.index;
    },
    SET_ERROR_LABELS(state, errorMsg) {
        state.errorMsg = errorMsg;
    },
    SHOW_ERRORS(state, status) {
        state.isError = status;
    },
    UPDATE_COLOR(state, profile) {
        state.colorChoice = profile.Hex ? profile.Hex : profile;
        state.colorProfile = profile.Hex ? profile : '';
    },
    UPDATE_TOOL_STATE(state, stage) {
        state.toolState = toolStage[stage];
    },
    SET_EYE_SHADOW(state, eyeShadows) {
        state.eyeShadows = eyeShadows;
    },
    SET_BLUSH(state, blushArray) {
        state.blushArray = blushArray;
    },
    UPDATE_OVERLAY_IMAGE(state, face) {
        state.overlayImageUrl = face.ImageUrl;
    },
    SET_SELECTED_SKU(state, sku) {
        state.selectedSku = sku;
    },
    UPDATE_COORDINATES(state) {
        Object.keys(cNcoordinates).forEach(key => {
            state.coordinates[key] = {
                ...state.coordinates[key],
                ...cNcoordinates[key]
            };
        });
    }
};

export default {
    namespaced,
    state,
    mutations,
    getters,
    actions
};
